import { test } from "node:test";
import assert from "node:assert/strict";
import { MO_GLYPH_BOX, MO_GLYPH_PATH } from "../shared/mo-glyph.js";

test("mo-glyph: closed subpaths, absolute commands only, every point inside the box", () => {
  assert.match(MO_GLYPH_PATH, /^M/);
  assert.match(MO_GLYPH_PATH, /Z$/);
  // Only the absolute commands the extractor emits; a relative command or an
  // arc would mean the data was regenerated by something else.
  assert.equal(MO_GLYPH_PATH.replace(/[MLCQZ0-9. -]/g, ""), "");
  const nums = MO_GLYPH_PATH.match(/-?\d+(?:\.\d+)?/g)!.map(Number);
  assert.ok(nums.length > 300, `expected a real outline, got ${nums.length} numbers`);
  for (const n of nums) {
    assert.ok(n >= 0 && n <= MO_GLYPH_BOX, `${n} falls outside [0, ${MO_GLYPH_BOX}]`);
  }
  // The glyph is centered: its extent should be symmetric about the box center.
  const xs = nums.filter((_, i) => i % 2 === 0);
  const ys = nums.filter((_, i) => i % 2 === 1);
  const mid = MO_GLYPH_BOX / 2;
  assert.ok(Math.abs(Math.min(...xs) + Math.max(...xs) - 2 * mid) < 2);
  assert.ok(Math.abs(Math.min(...ys) + Math.max(...ys) - 2 * mid) < 2);
});
